source='''def transform(grid):
    h, w = len(grid), len(grid[0])
    # Separator color fills complete divider rows and columns.
    sep_candidates = {grid[r][0] for r in range(h) if all(v == grid[r][0] for v in grid[r])}
    sep_candidates |= {grid[0][c] for c in range(w) if all(grid[r][c] == grid[0][c] for r in range(h))}
    sep = max(sep_candidates, key=lambda x: sum(v == x for row in grid for v in row))
    row_blocks, col_blocks = [], []
    start = 0
    for r in range(h):
        if all(v == sep for v in grid[r]):
            if start < r:
                row_blocks.append((start, r))
            start = r + 1
    if start < h:
        row_blocks.append((start, h))
    start = 0
    for c in range(w):
        if all(grid[r][c] == sep for r in range(h)):
            if start < c:
                col_blocks.append((start, c))
            start = c + 1
    if start < w:
        col_blocks.append((start, w))
    colors = {v for row in grid for v in row if v != sep}
    background = max(colors, key=lambda x: sum(v == x for row in grid for v in row))
    marker = next(x for x in colors if x != background)
    out = [[background for _ in col_blocks] for _ in row_blocks]
    for i, (r0, r1) in enumerate(row_blocks):
        for j, (c0, c1) in enumerate(col_blocks):
            if any(grid[r][c] == marker and grid[r][c+1] == marker
                   for r in range(r0, r1) for c in range(c0, c1-1)):
                out[i][j] = 1
    return out
'''
